CSS Starter:
body { background: var(--bg); color: var(--text); }
.poster { aspect-ratio: 2 / 3; border-radius: var(--radius); object-fit: cover; }
.tabbar { padding-bottom: env(safe-area-inset-bottom); }

.display { font: 900 clamp(3rem, 18vw, 8rem)/0.9 'Anton', sans-serif; text-transform: uppercase; }
.block { border: var(--edge); background: var(--signal); }
.marquee { animation: slide 20s linear infinite; }

body { font: 1.1875rem/1.5 'Public Sans', sans-serif; color: var(--ink); }
a { color: var(--link); text-decoration: underline; }
:focus-visible { outline: 3px solid var(--focus); outline-offset: 0; box-shadow: 0 4px 0 #0B0C0C; }
